import logging
from datetime import datetime, time, timedelta

import requests
from attrdict import AttrDict

from ..fm_http_client import FmHttpClient

requests.packages.urllib3.disable_warnings()  # type: ignore[attr-defined]
logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class FmRestApiMixin:

    @property
    def http_client(self):
        return FmHttpClient(self.nodes.web_url,
                            self.nodes.web_username,
                            self.nodes.web_password)

    def get_alarms(self, dist_name, only_active=True):
        """
        Get all alarms.

        Example output:
        ***************
        ::

            [
                {
                    'alarmKey':
                        {
                            'alarmId': 881
                        },
                    'dn': 'PLMN-PLMN/MRBTS-1/LNBTS-917/LNMME-0',
                    'probableCauseCode': 0,
                    'clearUser': None,
                    'eventType': 'COMMUNICATION',
                    'clearTime': None,
                    'specificProblem': 7656,
                    'additionalText1': 'shared:N;Transport layer connection failure in S1 interface',
                    'additionalText2': None,
                    'additionalText3': '100 100 100 6202 0 0 dstIPAddr:10.68.221.106;additionalFaultId:6202;',
                    'additionalText4': None,
                    'additionalText5': None,
                    'additionalText7': None,
                    'additionalText6': None,
                    'alarmText': 'BASE STATION CONNECTIVITY LOST',
                    'alarmState': 'ACTIVE',
                    'perceivedSeverity': 'CRITICAL',
                    'alarmCount': 1,
                    'alarmTime': '2018-09-12T16:08:03.000+0300',
                    'ackStatus': 'UNACKED',
                    'additionalAttributes':
                        {
                            'originalSeverity': 'indeterminate',
                            'originalAlarmId': '1570172368',
                            'liftedDN': 'PLMN-PLMN/MRBTS-1/LNBTS-917'
                        },
                    'ackUser': None,
                    'rootCauseAlarm': 'FALSE',
                    'ackTime': None
                }, ...
            ]

        :param string dist_name: Front part of the name must match literally to the searched one and at the end
            the wildcard will be added automatically. If full dist_name looks like, for example,
            PLMN-PLMN/MRBTS-123456/LNBTS-123456/FTM-1, the front part must be given: PLMN-PLMN/MRBTS-123456
        :param bool only_active: If True, gets all the active alarms i.e. all the alarms that are not cleared.
            Otherwise, gets all the alarms i.e. all the alarms that are not cleared and acknowledged.
        :return: Alarms
        :rtype: list(dict)
        """
        endpoint = '/fm-access/api/fm/query/v1/alarms'
        headers = self._create_rest_api_headers(
            accept='application/vnd.nokia-alarm-query-response-v1+json;charset=utf-8',
            content_type='application/vnd.nokia-alarm-query-filter-request-v1+json;charset=utf-8')
        params = {'active': only_active}
        dist_name = dist_name.rstrip('/')  # to keep backward compatibility with previous definition of filters
        data = {
            'filters':
                [
                    {
                        'relationalCriteria':
                            [
                                {
                                    'operator': 'LIKE_IGNORECASE',
                                    'attributeValue': f'{dist_name}/*',
                                    'attributeName': 'dn'
                                }
                            ]
                    },
                    {
                        'relationalCriteria':
                            [
                                {
                                    'operator': 'EQUALS_IGNORECASE',
                                    'attributeValue': dist_name,
                                    'attributeName': 'dn'
                                }
                            ]
                    }
                ]
        }
        return [AttrDict(alarm) for alarm in self.http_client.send_request(
            'POST', endpoint, headers, params=params, data=data)]

    def get_cleared_alarms(self, dist_name, time_from, time_to):
        """
        Gets all the cleared alarms i.e. all the alarms that are acknowledged and cleared.

        Example output:
        ***************
        ::

            [
                {
                    'ackStatus': 'ACKED',
                    'ackTime': '2021-09-13T03:06:23.000+0300',
                    'ackUser': 'WITHCANCEL',
                    'additionalAttributes':
                        {
                            'internalAlarm': '0',
                            'liftedDN': 'PLMN-PLMN/MRBTS-1234/LNBTS-1234',
                            'ocId': 'LNBTS:MRBTS',
                            'originAckUnackTime': '2021-09-13T03:06:23+03:00',
                            'originAlarmTime': '2021-09-13T07:55:16+08:00',
                            'originCancelTime': '2021-09-13T08:06:22+08:00',
                            'originalAlarmId': 'b9908038aab1704151606339b90de59b689e7ced',
                            'originalSeverity': 'minor',
                            'relatedDNS': None,
                            'severity': 'MINOR'
                        },
                    'additionalText1': 'Fan failure',
                    'additionalText2': None,
                    'additionalText3': '4078 unitName=FSM_FAN ... additionalFaultID=3050 SMOD-1',
                    'additionalText4': None,
                    'additionalText5': None,
                    'additionalText6': None,
                    'additionalText7': None,
                    'alarmCount': 1,
                    'alarmKey':
                        {
                            'alarmId': 4999494
                        },
                    'alarmState': 'CLEARED',
                    'alarmText': 'BASE STATION NOTIFICATION',
                    'alarmTime': '2021-09-13T02:55:16.000+0300',
                    'clearTime': '2021-09-13T03:06:22.000+0300',
                    'clearUser': None,
                    'dn': 'PLMN-PLMN/MRBTS-1234/LNBTS-1234',
                    'eventType': 'EQUIPMENT',
                    'perceivedSeverity': 'CLEARED',
                    'probableCauseCode': 0,
                    'rootCauseAlarm': 'TRUE',
                    'specificProblem': 7652
                }, ...
            ]

        :param string dist_name: Front part of the name must match literally to the searched one
            and at the end the wildcard will be added automatically. If full dist_name looks like e.g.:
            PLMN-PLMN/MRBTS-100826/LNBTS-100826/FTM-1 front part must be given: PLMN-PLMN/MRBTS-100826
        :param datetime time_from: Start of the time range in UTC timezone.
        :param datetime time_to: End of the time range in UTC timezone.
        :return: cleared alarms
        :rtype: list(dict)
        """
        endpoint = '/fm-access/api/fm/query/v1/alarms/cleared/filter'
        headers = self._create_rest_api_headers(
            accept='application/vnd.nokia-alarm-clear-response-v1+json;charset=utf-8',
            content_type='application/vnd.nokia-alarm-clear-request-v1+json;charset=utf-8')
        data = {
            'filters':
                [
                    {
                        'relationalCriteria':
                            [
                                {
                                    'operator': 'LIKE_IGNORECASE',
                                    'attributeValue': f'{dist_name}/*',
                                    'attributeName': 'dn'
                                }
                            ]
                    },
                    {
                        'relationalCriteria':
                            [
                                {
                                    'operator': 'EQUALS_IGNORECASE',
                                    'attributeValue': dist_name,
                                    'attributeName': 'dn'
                                }
                            ]
                    }
                ]
        }
        alarms = []
        for time_from, time_to in self._terminated_time_ranges(time_from, time_to):
            data['terminatedTimeFrom'] = time_from
            data['terminatedTimeTo'] = time_to
            alarms += self.http_client.send_request('POST', endpoint, headers, data=data)
        return [AttrDict(alarm) for alarm in alarms]

    def get_alarms_based_on_template(self, **alarm_template):
        """
        Gets all alarms that match provided alarm template.

        Example output:
        ***************
        ::

            [
                {
                    'alarmKey':
                        {
                            'alarmId': 881
                        },
                    'dn': 'PLMN-PLMN/MRBTS-1/LNBTS-917/LNMME-0',
                    'probableCauseCode': 0,
                    'clearUser': None,
                    'eventType': 'COMMUNICATION',
                    'clearTime': None,
                    'specificProblem': 7656,
                    'additionalText1': 'shared:N;Transport layer connection failure in S1 interface',
                    'additionalText2': None,
                    'additionalText3': '100 100 100 6202 0 0 dstIPAddr:10.68.221.106;additionalFaultId:6202;',
                    'additionalText4': None,
                    'additionalText5': None,
                    'additionalText7': None,
                    'additionalText6': None,
                    'alarmText': 'BASE STATION CONNECTIVITY LOST',
                    'alarmState': 'ACTIVE',
                    'perceivedSeverity': 'CRITICAL',
                    'alarmCount': 1,
                    'alarmTime': '2018-09-12T16:08:03.000+0300',
                    'ackStatus': 'UNACKED',
                    'additionalAttributes':
                        {
                            'originalSeverity': u'indeterminate',
                            'originalAlarmId': u'1570172368',
                            'liftedDN': u'PLMN-PLMN/MRBTS-1/LNBTS-917'
                        },
                    'ackUser': None,
                    'rootCauseAlarm': u'FALSE',
                    'ackTime': None
                }, ...
            ]

         :param \\** alarm_template: available parameters: alarmKey, dn, probableCauseCode, alarmTime, specificProblem,
             alarmText, perceivedSeverity, additionalText1, additionalText2, additionalText3, additionalText4,
             additionalText5, additionalText6, additionalText7, eventType, ackStatus, ackTime, ackUser, rootCauseAlarm,
             alarmCount
         :return: alarm details
         :rtype: list(dict)
         """
        endpoint = '/fm-access/api/fm/query/v1/template-alarms'
        headers = self._create_rest_api_headers(
            accept='application/vnd.nokia-alarm-query-template-response-v1+json;charset=utf-8',
            content_type='application/vnd.nokia-alarm-query-template-request-v1+json;charset=utf-8'
        )
        data = {
            'alarmTemplate': alarm_template
        }
        return [AttrDict(alarm) for alarm in self.http_client.send_request('POST', endpoint, headers, data=data)]

    @staticmethod
    def _create_rest_api_headers(accept, content_type, x_http_method_override='GET'):
        return {
            'Accept': accept,
            'Content-Type': content_type,
            'X-HTTP-Method-Override': x_http_method_override
        }

    def _terminated_time_ranges(self, time_from, time_to):
        """
        Split given time range to fulfil API restriction,
        TerminatedTimeFrom and TerminatedTimeTo must be on the same day.

        Example output:
        ***************
        ::

            [
                ['2021-09-11T23:45:00.000+0000', '2021-09-11T23:59:59.999+0000'],
                ['2021-09-12T00:00:00.000+0000', '2021-09-12T23:59:59.999+0000'],
                ['2021-09-13T00:00:00.000+0000', '2021-09-13T00:15:00.000+0000']
            ]

        :param datetime time_from: Start of the time range.
        :param datetime time_to: End of the time range.
        :return: time ranges in format required by terminatedTimeFrom/terminatedTimeTo
        :rtype: list(list)
        """
        dates = [
            time_from.date() + timedelta(days)
            for days in range((time_to.date() - time_from.date()).days + 1)
        ]
        time_ranges = [
            [self._terminated_time_format(datetime.combine(date, time(0, 0, 0))),
             self._terminated_time_format(datetime.combine(date, time(23, 59, 59)), ms='999')]
            for date in dates
        ]
        time_ranges[0][0] = self._terminated_time_format(time_from)
        time_ranges[-1][-1] = self._terminated_time_format(time_to)
        return time_ranges

    @staticmethod
    def _terminated_time_format(date_time, ms='000'):
        """
        Convert datetime to format "yyyy-MM-dd'T'HH:mm:ss.SSSZ" required by terminatedTimeFrom/terminatedTimeTo

        :param datetime.datetime date_time:
        :param string ms: milliseconds in format SSS, e.g. 000 or 999
        :return: time in format required by terminatedTimeFrom/terminatedTimeTo
        :rtype: string
        """
        date_time = date_time.replace(microsecond=0).isoformat(sep='T')
        tz = '+0000'
        return f'{date_time}.{ms}{tz}'
